import React, { useState, useEffect } from "react";
import { Trans, useTranslation } from "gatsby-plugin-react-i18next";
import { Link } from "gatsby";
import { FiMenu, FiX } from "react-icons/fi";
import { FaArrowUp } from "react-icons/fa";
import { motion, AnimatePresence } from "framer-motion";

interface NavProps {
  data?: {
    menu: string[];
  };
}

const Navigation: React.FC<NavProps> = ({ data }) => {
  const { t } = useTranslation();
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [showBackToTop, setShowBackToTop] = useState(false);

  if (!data || !data.menu) {
    return null;
  }

  const toggleMenu = () => {
    setIsMenuOpen((prev) => !prev);
  };

  const scrollToTop = () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  useEffect(() => {
    const handleScroll = () => {
      setShowBackToTop(window.scrollY > 100);
    };
    window.addEventListener("scroll", handleScroll);
    return () => {
      window.removeEventListener("scroll", handleScroll);
    };
  }, []);

  return (
    <nav className={styles.container}>
      {/* Botón para menú en mobile */}
        <button onClick={toggleMenu} className={styles.burgerButton}>
          {isMenuOpen ? (
            <FiX className="text-secondary fixed right-4 z-[70] top-4" size={36} />
          ) : (
            <FiMenu className="text-secondary mx-8" size={36} aria-label="Toggle menu" />
          )}
        </button>

      {/* Menú en desktop siempre visible */}
      <ul className={`${styles.buttonsWrapper} hidden md:grid`}>
        {data.menu.map((item: string, index: number) => (
          <li key={index} className={styles.buttons}>
            <Link
              activeClassName={styles.active}
              to={item === "home" ? `/` : `/${item}`}
             
              onClick={() => setIsMenuOpen(false)}
            >
              <Trans className="w-full h-full" i18nKey={`menu.${item}`}>{t(`menu.${item}`)}</Trans>
            </Link>
          </li>
        ))}
      </ul>

      {/* Menú en mobile con animación */}
      <AnimatePresence>
        {isMenuOpen && (
          <motion.ul
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            className={`${styles.mobileMenu} md:hidden`}
          >
            {data.menu.map((item: string, index: number) => (
              <li key={index}>
                <Link
                  activeClassName={styles.active}
                  to={item === "home" ? `/` : `/${item}`}
                  className={styles.buttons}
                  onClick={() => setIsMenuOpen(false)}
                >
                  <Trans i18nKey={`menu.${item}`}>{t(`menu.${item}`)}</Trans>
                </Link>
              </li>
            ))}
          </motion.ul>
        )}
      </AnimatePresence>

      {/* Botón "Volver arriba" */}
      {showBackToTop && (
        <button onClick={scrollToTop} className={styles.backToTopButton}>
          <FaArrowUp size={20} />
        </button>
      )}
    </nav>
  );
};

export default Navigation;

const styles = {
  container: "flex justify-between items-center px-4 py-2 mx-0 sm:mx-8 z-10",
  burgerButton: "md:hidden block focus:outline-none mx-auto",
  buttonsWrapper: " grid-cols-3 gap-4 bg-transparent",
  // buttonsWrapper: "flex flex-row justify-evenly items-center w-full bg-transparent",
  buttons: "nav-element bg-primary hover:bg-accent text-accent hover:text-neutral text-xl shadow-xl shadow-warning-500 rounded-lg line-clamp-2 text-center flex-1 px-16 sm:px-0",
  mobileMenu:
    "fixed inset-0 bg-white flex flex-col items-center justify-center space-y-4 shadow-lg z-50",
  backToTopButton: "text-neutral bg-accent fixed bottom-4 right-4 p-2 rounded-full shadow-lg z-50",
  active: "!text-neutral !bg-accent",
};
